// Собрать сообщение для менеджера из списка «зависших» лидов.
// Telegram ограничивает сообщение ~4096 символами, поэтому длинный список
// разбивается на несколько частей: порядок лидов сохраняется, ни один не теряется.
const SAFE_LIMIT = 3800;
const items = ($json.body && $json.body.items) || [];
if (items.length === 0) { return []; }

const emoji = { stale: '🔴', remind: '🟡', unresolved: '⚠️' };
const lines = items.map((item) => {
  const mark = emoji[item.bucket] || '•';
  return `${mark} #${item.lead_id} ${item.full_name} ${item.phone} — ${item.bucket}, ${item.age_hours} ч, статус: ${item.status}`;
});

const header = `Follow-up: ${items.length} лидов требуют внимания`;
const budget = SAFE_LIMIT - header.length - 1;

const parts = [];
let current = [];
let length = 0;

for (const line of lines) {
  const projected = length + (current.length ? 1 : 0) + line.length;
  if (current.length && projected > budget) {
    parts.push(current);
    current = [];
    length = 0;
  }
  current.push(line);
  length += (current.length > 1 ? 1 : 0) + line.length;
}
if (current.length) { parts.push(current); }

return parts.map((part, index) => ({
  json: {
    count: items.length,
    part: index + 1,
    parts_total: parts.length,
    text: `${header}\n${part.join('\n')}`,
  },
}));
